CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL, label TEXT, created_at INTEGER NOT NULL, event_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'created', premium INTEGER NOT NULL DEFAULT 0, premium_answer TEXT, duration_min INTEGER NOT NULL DEFAULT 90, vars TEXT NOT NULL, secrets TEXT NOT NULL, join_code TEXT NOT NULL UNIQUE, org_code TEXT NOT NULL UNIQUE, org_token TEXT, test_mode INTEGER NOT NULL DEFAULT 0, opened_at INTEGER, started_at INTEGER, ended_at INTEGER);
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, core_at INTEGER, solved_at INTEGER, penalty_min INTEGER NOT NULL DEFAULT 0, wrong INTEGER NOT NULL DEFAULT 0, last_attempt_at INTEGER, last_result TEXT, tips TEXT NOT NULL DEFAULT '[]', UNIQUE (session_id, name));
CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, team_id TEXT NOT NULL, at INTEGER NOT NULL, payload TEXT NOT NULL, correct INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_teams_session ON teams(session_id);
CREATE INDEX IF NOT EXISTS idx_attempts_team ON attempts(team_id);
